api.look('agent');
const cx = api.w/2, cy = 330;
const k = api.seg(t, 0, 1.4);
api.path('M-120 -70 L120 -70 L120 70 L-120 70 Z', {x:cx, y:cy, s:1.2, c:'fg', w:4, fill:'panel', k});
