api.look('agent');
const cx = api.w/2;
for (let i = 0; i < 12; i++) {
  const p = api.stag(t, i, {gap:0.25, dur:0.5, from:0.2});
  const col = i % 3, row = Math.floor(i / 3);
  const x = cx - 105 + col*105, y = 200 + row*110;
  api.box(x, y, 84, 62, {c:'fg', w:3, fill:'panel', k:p});
  api.path('M-24 -12 L0 8 L24 -12', {x, y, s:1, c:'a2', w:3, k:p});
  const d = api.seg(t, 0.6 + i*0.3, 1.0 + i*0.3);
  api.shape('check', x+30, y-22, 26, {c:'good', w:4, k:d});
}
api.counter(12, cx, 700, {k:api.seg(t,0.5,4), size:56, c:'good', suf:' / 12'});
api.text('all answered', cx, 740, {size:22, align:'center', k:api.seg(t,4,5)});
api.say('Every one got a reply', 0.5, 5.5);

api.look('agent');
const cx = api.w/2, cy = 330;
const pts = [[60,cy],[130,cy],[200,cy],[270,cy],[340,cy]];
api.line(50, cy, 340, cy, {c:'fg', w:5, k:api.seg(t,0,1)});
const bx = api.lerp(0,1,api.seg(t,1,1.4));
const gap = 40*bx;
api.line(cx-30-gap, cy-45*bx, cx-10, cy+0, {c:'bad', w:4, a:1-api.seg(t,2.5,3.2)});
api.shape('cross', 120, cy-70, 44, {c:'bad', w:5, k:api.seg(t,1,1.8), a:1-api.seg(t,2.6,3.2)});
api.shape('cross', 270, cy-70, 44, {c:'bad', w:5, k:api.seg(t,1.4,2.2), a:1-api.seg(t,3,3.6)});
api.shape('check', 120, cy-70, 44, {c:'good', w:5, k:api.seg(t,3,3.8)});
api.shape('check', 270, cy-70, 44, {c:'good', w:5, k:api.seg(t,3.6,4.4)});
api.scribble(120, cy-70, 40, 40, {k:api.seg(t,1,1.8), a:1-api.seg(t,2.8,3.2)});
api.counter(2, cx, cy+170, {k:api.seg(t,0.5,2.5), size:72, c:'accent'});
api.text('broken links fixed', cx, cy+225, {size:24, align:'center', k:api.seg(t,2,3)});
api.say('Two broken links, fixed', 0.3, 5.5);

api.look('agent');
const cx = api.w/2, cy = 340;
api.rect(cx-130, cy-190, 260, 380, {c:'fg', w:4, fill:'panel', k:api.seg(t,0,1)});
api.text('NEWSLETTER', cx, cy-150, {size:26, weight:700, align:'center', c:'accent', k:api.seg(t,0.8,1.6)});
api.rect(cx-100, cy-110, 200, 60, {c:'a3', w:3, fill:'a3', a:0.3, k:api.seg(t,1.4,2.2)});
for (let i = 0; i < 5; i++) {
  const y = cy - 20 + i*34;
  const w = i === 4 ? 110 : 200;
  api.line(cx-100, y, cx-100+w*api.seg(t,2+i*0.5,2.6+i*0.5), y, {c:'dim', w:4});
}
api.text('Next week', cx, cy+230, {size:28, weight:700, align:'center', k:api.seg(t,3.5,4.5)});
api.label('DRAFT', cx+90, cy-170, {k:api.seg(t,4.5,5.2)});
api.cam(0, 0, api.lerp(1, 1.12, api.ease(api.seg(t,0,6))), 0);
api.say('Next week\'s newsletter drafted', 0.3, 5.5);

api.look('agent');
const cx = api.w/2;
api.bars([
  {label:'Emails', v:12, c:'accent'},
  {label:'Links', v:2, c:'a2'},
  {label:'Newsletter', v:1, c:'a3'}
], 50, 180, api.w-100, 420, {k:api.seg(t,0,2.5)});
api.shape('check', cx, 680, 70, {c:'good', w:6, k:api.seg(t,3,4.2)});
api.text('Done', cx, 740, {size:36, weight:700, align:'center', k:api.seg(t,3.6,4.6)});
api.say('A full day, done', 0.4, 5.5);
